/** Trechos literais de copel-ntc900600.json (relatório e avisos). */
export const COPEL_NTC900600_TRECHOS = [
  { fonte: NTC_900600, item: "3.1.1", pagina: 1, texto: "3.1.1 - Cálculo da relação kVA/ apartamento através da fórmula Y = 0,034939 . X^0,895075 , onde Y é a demanda em kVA e X é a área útil do apartamento em m2; ou através da Tabela 1, que é o desenvolvimento da referida fórmula para apartamentos com área útil de até 400 m2." },
  { fonte: NTC_900600, item: "3.1.1", pagina: 1, texto: "O critério permite o cálculo da demanda dos apartamentos para unidades com área útil a partir de 20 m2. Além disso, para apartamentos com área útil de 20 a 42 m2, deverá ser adotado o valor de 1,0 kVA por apartamento, conforme pode ser observado na Tabela 1." },
  { fonte: NTC_900600, item: "3.1.2", pagina: 2, texto: "3.1.2 - Cálculo da diversidade em função da quantidade de apartamentos do edifício pela utilização da Tabela 2, aplicável  a edifícios com até 300 apartamentos." },
  { fonte: NTC_900600, item: "3.1.3", pagina: 2, texto: "3.1.3 - Cálculo da demand dos apartamentos através do produto do valor da demanda de uma unidade, determinado no item 3.1.1, pelo valor de diversidade obtido no item 3.1.2." },
  { fonte: NTC_900600, item: "3.2.1", pagina: 2, texto: "3.2.1 - Cálculo da parcela de demanda referente às cargas de iluminação / a - Devem ser aplicados os seguintes percentuais à carga total instalada e, kW: - 100% para os primeiros 10 kW - 25% para o que exceder a 10 kW / b - Ao valor encontrado em kW, deve ser aplicado o fator de potência específico considerado no projeto." },
  { fonte: NTC_900600, item: "3.2.2", pagina: 2, texto: "3..2.2 - Cálculo da parcela de demanda referente às cargas de tomadas / a - Deve ser aplicado o percentualk 20% à carga total instalada em kW / b - Ao valor encontrado em kW, deve ser aplicado o fator de potência específico considerado no projeto." },
  { fonte: NTC_900600, item: "3.2.3", pagina: 2, texto: "3.2.3 - Cálculo da parcela de demanda referente a elevadores e bombas d'água / Deve ser aplicada a Tabela 3, separadamente, para os grupos de motores de elevadores e de bombas d'água, adotando-se o fator de diversidade 1,0 para estes grupos." },
  { fonte: NTC_900600, item: "3.2.4", pagina: 2, texto: "3.2.4 - Cálculo das parcelas de demanda referentes a outras cargas do condomínio / a - cargas motrizes / Deve ser aplicada a Tabela 3 para cada tipo de carga, adotando-se o fator de diversidade 1,0 a cada grupo destas cargas. / b - Cargas não motrizes" },
  { fonte: NTC_900600, item: "3.2.4 b", pagina: 3, texto: "Estas cargas deverão ser analisadas em particular, aplciando-se às mesmas, fator de demanda em função das suas características de utilização definidas no projeto. / Sobre a demanda calculada apra estas cargas, deverá ser considerado o fator de diversidade 1,0. / Para estas cargas, deve ser adotado o fator de potência específico, previsto no projeto." },
  { fonte: NTC_900600, item: "3.2.5", pagina: 3, texto: "3.2.5 - Cálculo de Demanda do Condomínio / A demanda total do condomínio deve ser calculada pela soma das demandas parciais do condomínio." },
  { fonte: NTC_900600, item: "3.3.1", pagina: 3, texto: "3.3.1 - A demanda total do edifício deve ser determinada pela soma da demanda dos apartamentos e da demanda do condomínio." },
  { fonte: NTC_900600, item: "3.3.3", pagina: 3, texto: "3.3.3 - Recomenda-se que o dimensionamento da demanda total do edifício seja feito de modo que a corrente considerada não seja inferior à corrente correspondente à potência de 26 kVA mais a demanda do condomínio. Tal medida visa dotar o sistema de proteção das instalações internas do edifício da seletividade necessária, garantindo que a proteção de cada unidade tenha capacidade de corrente inferior à da proteção geral." },
  { fonte: NTC_900600, item: "4.1", pagina: 3, texto: "4.1 - Emprego do Critério pela COPEL / No dimensionamento dos materiais e equipamentos das entradas de serviço de responsabilidade da COPEL, recomenda-se a adoção do critério proposto, com utilização de um fator multiplicador da demanda total calculada igual a 1,0." },
  { fonte: NTC_900600, item: "4.2", pagina: 4, texto: "4.2 - Emprego do Critério por Projetistas / No cálculo das demandas constantes em projeto, recomenda-se a adoção do critério com emprego de um fator multiplicador da demanda total calculada igual a 1,2. / Nos casos em que o projetista julgar conveniente, pelas características específicas do projeto, poderá optar pela adoção de um fator multiplicador superior a 1,2. / O projetista poderá adotar outros critérios diferentes do critério proposto, desde que os valores de demanda calculados através dos mesmos não sejam inferiores aos valores calculados pelo critério proposto multiplicado pelo fator 1,2. / Independentemente do critério de cálculo de demanda adotado no projeto, deve ficar entendido que a responsabilidade pelo referido cálculo é do projetista. / O dimensionamento dos materiais e equipamentos de responsabilidade do consumidor deve ser feito com base no critério de demanda adotado pelo projetista." },
  { fonte: NTC_900600, item: "5.1", pagina: 4, texto: "5.1 - Características das Cargas do Edifício / a - Características dos Apartamentos / - área útil dos apartamentos / - 12 unidades com 97 m2 / - 18 unidades com 121 m2 / - nº total de apartamentos: 30 / b - Carga do Condomínio / - carga instalada de iluminação: 15 kW (fator de potência 0,9) / - carga instalada de tomadas: 8 kW (fator de potência 0,8) / - 2 elevadores com potência unitária 10cv / - 4 bombas d'água com potência unitária 2 cv (duas são de reserva) / - 1 central de ar condicionado de 8,3 kW (fator de potência 0,8)" },
  { fonte: NTC_900600, item: "5.2", pagina: 6, texto: "5.2 - Cálculo da Demanda dos Apartamentos / - média ponderada das áreas úteis: 12 x 97 + 18 x 121/ 12 + 18 = 111,4 m2 / valor a considerar: 111 m2 / - Aplicando-se o valor 111 m2 na Tabela 1, ou na expressão Y = 0,034939 X^0,895075 , obtém-se o valor de 2,37 kVA para a demanda a ser considerada para uma unidade. / - Na Tabela 2, determina-se a diversidade em função do número total de apratamentos: 30 corresponde a 23,48. / - O produto da demanda de uma unidade pelo valor de diversidade determina a demanda dos apartamentos" },
  { fonte: NTC_900600, item: "5.2 (cont.)", pagina: 5, texto: "- 2,37 kVA x 23,48 = 55,65 kVA / - demanda dos apartamentos = 55,65 kVA" },
  { fonte: NTC_900600, item: "5.3", pagina: 5, texto: "5.3 - Cálculo da Demanda do Condomínio / a - cargas de iluminação / - carga instalada total: 15 kW / - fator de potência: 0,9 / - 100% de 10 kW = 10 kW / - 25% de 5 kW = 1,25 kW / 11,25 kW / 0,9 = 12,5 kVA / b - cargas de tomadas / - carga instalada total: 8 kW / - fator de potência: 0,8 / - 20% de 8 kW = 1,6 kW : 0,8 = 2,0 kVA / c - cargas de elevadores / - 2 motores de 10 cv (trifásicos) / - da Tabela 3: 2 motores de 10 cv correspondem à demanda de 17,31 kVA / d - cargas de bombas d'água / - 4 motores de 2 cv trifásicos (dois de reserva) / - da Tabela 3: 2 motores de 2 cv correspondem à demanda de 4,05 kVA / e - outras cargas / - piscina: 2 motores de 1 cv (monofásicos) / - da Tabela 3: 2 motores de 1 cv monofásicos correspondem à demanda de 2,34 kVA / - central de ar condicionado: potência de 8,3 kW - fator de potência - 0,8 / f - demanda do condomínio / - demanda do condomínio = demanda das cargas de iluminação + demanda das cargas de tomadas + demanda dos elevadores + demanda das bombas d'água + demanda dos equipamentos da piscina + demanda da central de ar condicionado / demanda do condomínio = 48,58 kVA" },
  { fonte: NTC_900600, item: "5.4", pagina: 5, texto: "5.4 - Cálculo da Demanda Total do Edifício / - demanda total do edifício = demanda dos apartamentos + demanda do condomínio / demanda total do edifício = 55,65 + 48,58 = 104,23 kVA" },
] as const satisfies readonly TrechoNorma[];

