/** Trechos literais de copel-outras.json (relatório e avisos). */
export const COPEL_OUTRAS_TRECHOS = [
  { fonte: NTC_901110, item: "4.24 Determinação da Demanda", pagina: 31, texto: "A determinação das demandas parciais e total da edificação será de responsabilidade exclusiva do projetista, devendo estar coerente com a carga instalada e contemplar o uso de disjuntores de proteção e condutores adequados. A Copel não realizará a conferência dos cálculos adotados." },
  { fonte: NTC_901110, item: "5.1 Edificação com Demanda de até 76 kVA, alínea a)", pagina: 35, texto: "O atendimento à edificação com demanda de até 76 kVA (disjuntor geral até 200A) será realizado em baixa tensão (220/127V), derivado diretamente da rede de distribuição." },
  { fonte: NTC_901110, item: "5.1 Edificação com Demanda de até 76 kVA, alínea b)", pagina: 35, texto: "O atendimento deverá ser realizado com centro de medição único, sempre que a quantidade de unidades consumidoras for compatível com os limites do barramento longo conforme previsto na Tabela 7." },
  { fonte: NTC_901110, item: "5.2 Edificação com Demanda maior do que 76 kVA e menor ou igual a 300 kVA / 5.2.1 Tipo de Atendimento, alíneas a) e b)", pagina: 35, texto: "a) O atendimento a empreendimentos com demanda superior a 76 kVA e inferior ou igual a 300 kVA (disjuntor geral de até 800 A) será realizado a partir de transformador da Copel instalado na rede de distribuição. Para esse tipo de atendimento, será obrigatória a apresentação do projeto elétrico. b) Nesses casos, o atendimento será feito por meio de ramal de ligação subterrâneo em baixa tensão, derivado diretamente da rede de distribuição da Copel, com tensão de fornecimento de 220/127V, seguindo a Figura 14. (a alínea b) continua na página 36)" },
  { fonte: NTC_901110, item: "5.2.2 Ramal de Ligação Subterrâneo em Baixa Tensão, alínea a)", pagina: 36, texto: "Os condutores do ramal de ligação subterrâneo deverão ser de alumínio, com seção de 120 mm2 ou 185 mm2, isolação mínima XLPE 0,6/1 kV, dimensionados conforme a Tabela 4. Nas regiões litorâneas, os condutores deverão ser de cobre, seção 70 mm2 e 120 mm2 e isolamento XLPE 0,6/1 kV, conforme Tabela 4." },
  { fonte: NTC_901110, item: "5.3 Edificação com Demanda acima de 300 kVA / 5.3.1 Tipo de Atendimento, alínea a)", pagina: 36, texto: "O atendimento a empreendimentos com demanda superior a 300 kVA será realizado em média tensão por meio de transformador da Copel instalado em cabine localizada na entrada de serviço. Para esse tipo de atendimento, será obrigatória a apresentação do projeto elétrico." },
  { fonte: NTC_903100, item: "4.1 Limites de Fornecimento, alínea a)", pagina: 16, texto: "O fornecimento será efetuado em tensão primária de distribuição, quando a carga instalada na unidade consumidora for superior a 75 kW e a demanda de potência contratada ou estimada pelo interessado for igual ou inferior a 2 500 kW. A Copel poderá estabelecer a tensão de fornecimento, sem observar esses limites, quando a unidade consumidora incluir-se em casos previstos na legislação vigente." },
  { fonte: NTC_902210, item: "4.3", pagina: 5, texto: "É admitida a ligação em baixa tensão para unidades consumidoras com carga instalada acima de 75 kVA, limitada a 300 kVA, desde que exista viabilidade técnica para este atendimento." },
  { fonte: NTC_902210, item: "4.10", pagina: 5, texto: "Poderá ser dimensionada uma categoria de atendimento especial com disjuntor geral bifásico de 32A, exclusivamente para o atendimento às estações de recarga ligadas em centros de medição instalados em condomínios de uso coletivo, conforme abaixo: - Demanda máxima/carga instalada: 7 kVA; - Ramal alimentador: 6 mm²." },
  { fonte: NTC_902210, item: "8.1 Cálculo de Demanda", pagina: 8, texto: "Para o cálculo de demanda das instalações que contemplam estações de recargas de veículos elétricos, o responsável técnico pelo projeto deverá adotar fatores de demanda que tecnicamente atendam as diferentes condições de regime de funcionamento tanto das estações de recarga, quanto das demais cargas presentes nas instalações. Importante também considerar o tipo de utilização das estações." },
  { fonte: NTC_901100, item: "5.5.2 Dimensionamento da Entrada de Serviço", pagina: 36, texto: "O dimensionamento das entradas de serviço em agrupamento deverá ser feito de acordo com as características de cada categoria apresentadas na Tabela 2 e de acordo com as seguintes opções e considerações: i) Agrupamentos sem barramento e sem disjuntor geral: Será aceito agrupamento de até três unidades consumidoras monofásicas ou uma unidade bifásica agrupada a uma monofásica, ligadas nas fases A, B e C, conforme padrões construtivos do item 11.2.1 a 11.2.5. ii) Agrupamentos com barramento e disjuntor geral, através do somatório de corrente: Agrupamentos diferentes da condição estabelecida no inciso “i” deste item 5.5.2 e de categoria de atendimento determinada pela Tabela 3. iii) Agrupamentos com barramento e disjuntor geral, através de Formulário de Solicitação e ART de projeto elétrico da entrada de serviço: Agrupamentos diferentes das condições estabelecidas nos incisos “i” e “ii” deste item 5.5.2 e com a apresentação do Formulário de Solicitação de Medição Agrupada - FSMA e da ART – Anotação de Responsabilidade Técnica do projeto elétrico do agrupamento. Nesta opção de dimensionamento de agrupamento, também restrito aos casos de instalações com proteção geral máxima de 200 A e com a instalação de Centro de Medição único, será possível o seu dimensionamento sem considerar as definições da Tabela 3, ou seja, poderá ser considerado outros fatores de demanda para a especificação da proteção geral do agrupamento, diferente do proposto na Tabela 3." },
] as const satisfies readonly TrechoNorma[];
